return ['domain'=>'transparai','plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'es_ES','project-id-version'=>'TransparAI','pot-creation-date'=>'2026-09-08','po-revision-date'=>'2026-09-08','messages'=>['Detect AI images from C2PA Content Credentials and IPTC metadata, label them with a visible AI badge and a machine-readable EU AI Act disclosure.'=>'Detecta imágenes de IA a partir de las Content Credentials de C2PA y los metadatos IPTC, las señala con una insignia visible y una declaración legible por máquina para el Reglamento europeo de IA.','TransparAI'=>'TransparAI','This content is AI-generated'=>'Este contenido está generado por IA','Shows a short note ahead of the content. The wording can be changed in the TransparAI settings.'=>'Muestra un aviso breve delante del contenido. El texto se cambia en los ajustes de TransparAI.','Media is AI-generated'=>'El medio está generado por IA','The file metadata could not be updated (file not writable). The label state in WordPress and the metadata inside the file may differ.'=>'No se han podido actualizar los metadatos del archivo (archivo sin permiso de escritura). El estado de la etiqueta en WordPress y los metadatos dentro del archivo pueden diferir.','Confirm AI label'=>'Confirmar la etiqueta de IA','Not AI, dismiss'=>'No es IA, descartar','Re-check file metadata'=>'Volver a comprobar los metadatos del archivo','Check delivery'=>'Comprobar la entrega','Show file metadata'=>'Mostrar los metadatos del archivo','AI content'=>'Contenido de IA','Controls the front-end badge, the machine-readable file metadata and the media library filter.'=>'Controla la insignia pública, los metadatos escritos en el archivo y el filtro de la biblioteca de medios.','Default (site setting)'=>'Predeterminado (ajuste del sitio)','Top left'=>'Arriba a la izquierda','Top right'=>'Arriba a la derecha','Bottom left'=>'Abajo a la izquierda','Bottom right'=>'Abajo a la derecha','Caption line below the image'=>'Línea de pie debajo de la imagen','Hide the visible badge on this image'=>'Ocultar la insignia visible en esta imagen','Badge position'=>'Posición de la insignia','Overrides this image only. Use it if a theme overlay covers the badge here.'=>'Se aplica solo a esta imagen. Úsalo cuando una capa del tema tape la insignia aquí.','AI generator'=>'Generador de IA','Name of the AI tool, e.g. "Midjourney". Shown by the badge source option and the {generator} placeholder.'=>'Nombre de la herramienta de IA, por ejemplo «Midjourney». Lo muestra la opción de origen de la insignia y el marcador {generator}.','certain'=>'seguro','likely'=>'probable','hint'=>'indicio','You are not allowed to do that.'=>'No tienes permiso para hacer eso.','Unknown action.'=>'Acción desconocida.','Invalid attachment.'=>'Adjunto no válido.','Files'=>'Archivos','format cannot carry the declaration'=>'el formato no puede llevar la declaración','declaration present'=>'declaración presente','declaration missing'=>'declaración ausente','No readable file found for this attachment.'=>'No se ha encontrado ningún archivo legible para este adjunto.','Digital source type in the main file'=>'Digital source type en el archivo principal','None declared.'=>'Sin declaración.','Detection evidence'=>'Indicios de la detección','History'=>'Historial','system'=>'sistema','XMP packet of the main file'=>'Paquete XMP del archivo principal','This file carries no XMP block.'=>'Este archivo no contiene ningún bloque XMP.','AI status: all'=>'Estado de IA: todos','Only AI-labeled'=>'Solo los marcados como IA','Detected, needs review'=>'Detectado, pendiente de revisión','Without AI label'=>'Sin etiqueta de IA','Mark as AI-generated'=>'Marcar como generado por IA','Remove AI label'=>'Quitar la etiqueta de IA','Please select media first.'=>'Selecciona primero algún medio.','Updating the AI label failed.'=>'No se ha podido actualizar la etiqueta de IA.','Result'=>'Resultado','No AI provenance signals found in the file.'=>'No se han encontrado señales de procedencia de IA en el archivo.','The label was set, but the metadata could not be written into the file. Check the write permissions of the uploads directory.'=>'La etiqueta se ha guardado, pero los metadatos no se han podido escribir en el archivo. Revisa los permisos de escritura del directorio de subidas.','Hide file metadata'=>'Ocultar los metadatos del archivo','%1$d checked: %2$d delivered with the declaration, %3$d without, %4$d not comparable.'=>'%1$d comprobados: %2$d entregados con la declaración, %3$d sin ella, %4$d no comparables.','AI'=>'IA','Confirm detected AI label'=>'Confirmar la etiqueta de IA detectada','Dismiss detected AI label'=>'Descartar la etiqueta de IA detectada','AI label updated for %d media file.'=>'Etiqueta de IA actualizada en %d archivo de medios.' . "\0" . 'Etiqueta de IA actualizada en %d archivos de medios.','You are not allowed to export this.'=>'No tienes permiso para exportar esto.','The export could not be started.'=>'No se ha podido iniciar la exportación.','Settings'=>'Ajustes','%1$d scanned, %2$d auto-labeled, %3$d queued for review, %4$d skipped (already decided).'=>'%1$d analizados, %2$d etiquetados automáticamente, %3$d pendientes de revisión, %4$d omitidos (ya decididos).','Scan complete.'=>'Análisis completado.','Scan request failed. You can restart to continue.'=>'La petición de análisis ha fallado. Puedes reiniciarlo para continuar.','Settings saved.'=>'Ajustes guardados.','Library status'=>'Estado de la biblioteca','Media files'=>'Archivos de medios','Labeled as AI'=>'Etiquetados como IA','Waiting for review'=>'Pendientes de revisión','Scanned'=>'Analizados','Open review queue'=>'Abrir la cola de revisión','Export audit CSV'=>'Exportar la auditoría en CSV','The export lists every labeled and pending file with its detection source, confidence and the last recorded change.'=>'La exportación incluye cada archivo etiquetado o pendiente con su origen de detección, su nivel de confianza y el último cambio registrado.','Scan existing library'=>'Analizar la biblioteca existente','Reads the metadata of your existing media files (C2PA, XMP/IPTC, generator signatures) in small batches. Nothing leaves your server.'=>'Lee los metadatos de tus archivos de medios existentes (C2PA, XMP/IPTC, firmas de generadores) en lotes pequeños. Nada sale de tu servidor.','Scan new/unscanned media'=>'Analizar los medios nuevos o sin analizar','Rescan everything'=>'Volver a analizar todo','Pause'=>'Pausar','Auto-repair, last full sweep: %1$d labeled files checked, %2$d repaired, %3$d failed (%4$s ago).'=>'Reparación automática, último ciclo completo: %1$d archivos etiquetados comprobados, %2$d reparados, %3$d fallidos (hace %4$s).','Visible badge'=>'Insignia visible','Show badge'=>'Mostrar la insignia','Show a visible badge on labeled media in the front end'=>'Mostrar una insignia visible en los medios etiquetados de la parte pública','Start date'=>'Fecha de inicio','Only media uploaded on or after this date get the front-end badge; earlier media stay labeled in the admin only. Leave empty to badge all labeled media.'=>'Solo los medios subidos a partir de esta fecha reciben la insignia pública; los anteriores siguen etiquetados solo en la administración. Déjalo vacío para mostrar la insignia en todos los medios etiquetados.','Badge text'=>'Texto de la insignia','AI-generated'=>'Generado por IA','Leave empty for the translated default label.'=>'Déjalo vacío para usar el texto traducido por defecto.','Placeholders: %1$s (detected or manually set generator) and %2$s (site title), e.g. %3$s. Images without a known generator fall back to the default label.'=>'Marcadores: %1$s (generador detectado o introducido) y %2$s (título del sitio), por ejemplo %3$s. Las imágenes sin generador conocido usan el texto por defecto.','Appearance'=>'Aspecto','Overlay on the image'=>'Superpuesta a la imagen','Dark'=>'Oscura','Light'=>'Clara','Outline'=>'Contorno','Icon only (short label)'=>'Solo icono (texto corto)','Small'=>'Pequeña','Medium'=>'Mediana','Large'=>'Grande','Extras'=>'Extras','Show the detected generator in the badge (e.g. "AI-generated · Midjourney"; ignored when the badge text contains {generator})'=>'Mostrar el generador detectado en la insignia (por ejemplo «Generado por IA · Midjourney»; se ignora si el texto de la insignia contiene {generator})','Append the label to the image alt text (screen readers)'=>'Añadir la etiqueta al texto alternativo de la imagen (lectores de pantalla)','Automatically move a badge to another corner, or below the image, if a theme overlay covers it (recommended, needs JavaScript)'=>'Mover automáticamente la insignia a otra esquina, o debajo de la imagen, cuando una capa del tema la tape (recomendado, necesita JavaScript)','Also label images printed without an attachment ID (ACF fields, sliders, builders) and CSS backgrounds (experimental, needs JavaScript)'=>'Etiquetar también las imágenes mostradas sin ID de adjunto (campos ACF, carruseles, maquetadores) y los fondos CSS (experimental, necesita JavaScript)','Page notice'=>'Aviso de página','Add a short note at the end of pages that contain labeled media'=>'Añadir un aviso breve al final de las páginas que contienen medios etiquetados','This page contains AI-generated media.'=>'Esta página contiene medios generados por IA.','AI-generated text'=>'Texto generado por IA','Content note'=>'Aviso de contenido','This text was created with the help of AI.'=>'Este texto se ha creado con ayuda de IA.','Shown ahead of posts you mark with the "This content is AI-generated" checkbox in the editor sidebar.'=>'Se muestra delante de las entradas que marcas con la casilla «Este contenido está generado por IA» en la barra lateral del editor.','Automatic detection'=>'Detección automática','Detect on upload'=>'Detectar al subir','Inspect new uploads for AI provenance (C2PA, XMP/IPTC, generator signatures)'=>'Inspeccionar las subidas nuevas en busca de procedencia de IA (C2PA, XMP/IPTC, firmas de generadores)','Standard declarations'=>'Declaraciones formales','Label automatically'=>'Etiquetar automáticamente','Put into review queue'=>'Poner en la cola de revisión','Ignore'=>'Ignorar','Files that explicitly declare AI origin (IPTC DigitalSourceType, AI claim in C2PA, AIGC declaration).'=>'Archivos que declaran explícitamente un origen de IA (IPTC DigitalSourceType, declaración de IA en C2PA, declaración AIGC).','Generator signatures'=>'Firmas de generadores','Strong signals without a formal declaration (Stable Diffusion parameters, ComfyUI workflows, generator names in EXIF/XMP, camera-written C2PA).'=>'Señales fuertes sin declaración formal (parámetros de Stable Diffusion, flujos de ComfyUI, nombres de generadores en EXIF/XMP, C2PA escrito por una cámara).','More sources'=>'Más fuentes','Also scan video and audio uploads (MP4/MOV C2PA, MP3 AIGC declarations)'=>'Analizar también las subidas de vídeo y audio (C2PA en MP4/MOV, declaraciones AIGC en MP3)','Use filename patterns as review hints (never labels automatically)'=>'Usar los patrones del nombre de archivo como indicios para la revisión (nunca etiqueta automáticamente)','Machine-readable file metadata'=>'Metadatos legibles por máquina en los archivos','Write into files'=>'Escribir en los archivos','Write the IPTC DigitalSourceType as XMP into labeled JPEG, PNG, WebP and AVIF files (all size variants)'=>'Escribir el IPTC DigitalSourceType como XMP en los archivos JPEG, PNG, WebP y AVIF etiquetados (todos los tamaños generados)','Also mirror it into IPTC-IIM (JPEG, only when the file has no other IPTC block)'=>'Reflejarlo también en IPTC-IIM (JPEG, solo cuando el archivo no tiene otro bloque IPTC)','Auto-repair'=>'Reparación automática','Restore the metadata when image optimizers or regeneration strip it (hourly integrity sweep)'=>'Restaurar los metadatos cuando los optimizadores de imágenes o la regeneración de tamaños los eliminan (ciclo de integridad cada hora)','Delivery check'=>'Comprobación de la entrega','Allow checking whether the declaration survives delivery'=>'Permitir comprobar si la declaración sobrevive a la entrega','Adds a button to the attachment details and here. On click, the plugin fetches that image over its own public URL and compares the delivered bytes with the file on disk, which is the only way to notice that an optimizing CDN re-encodes your images and drops the declaration on the way out. The request goes to your own site and nowhere else, and it only ever happens when you press the button.'=>'Añade un botón aquí y en los detalles del adjunto. Al pulsarlo, el plugin descarga la imagen desde su propia URL pública y compara los bytes entregados con el archivo del disco, que es la única forma de notar que un CDN de optimización recodifica tus imágenes y elimina la declaración por el camino. La petición va a tu propio sitio y a ningún otro, y solo ocurre cuando pulsas el botón.','Check a sample of five files'=>'Comprobar una muestra de cinco archivos','Structured data'=>'Datos estructurados','Add Schema.org JSON-LD with the IPTC digital source type for the labeled media of each page (search engines read it without opening the files)'=>'Añadir JSON-LD de Schema.org con el digital source type de IPTC para los medios etiquetados de cada página (los buscadores lo leen sin abrir los archivos)','Uninstall'=>'Desinstalación','Data removal'=>'Eliminación de datos','Delete all plugin data (labels, detection results, settings) when the plugin is uninstalled'=>'Borrar todos los datos del plugin (etiquetas, resultados de detección, ajustes) al desinstalarlo','Save changes'=>'Guardar los cambios','TransparAI links'=>'Enlaces de TransparAI','Support forum'=>'Foro de soporte','The delivery check is switched off.'=>'La comprobación de la entrega está desactivada.','This attachment has no file.'=>'Este adjunto no tiene ningún archivo.','The file is served from another host, so it is not checked.'=>'El archivo se sirve desde otro host, así que no se comprueba.','The file on disk carries no AI declaration, so there is nothing to compare.'=>'El archivo del disco no lleva ninguna declaración de IA, así que no hay nada que comparar.','The image could not be fetched over its public URL.'=>'No se ha podido descargar la imagen desde su URL pública.','The response was not a readable image.'=>'La respuesta no era una imagen legible.','The declaration is present in the delivered file.'=>'La declaración está presente en el archivo entregado.','The delivered file carries no declaration. Something between WordPress and the visitor re-encodes the image, usually an optimizing CDN or a proxy.'=>'El archivo entregado no lleva ninguna declaración. Algo entre WordPress y el visitante recodifica la imagen, normalmente un CDN de optimización o un proxy.','Delivered with the declaration intact'=>'Entregado con la declaración intacta','Delivered without the declaration'=>'Entregado sin la declaración','Nothing to check'=>'Nada que comprobar','Served from another host'=>'Servido desde otro host','Could not be fetched'=>'No se ha podido descargar','short badge labelAI'=>'IA','This attachment is labeled as AI-generated, so every file below should carry the declaration.'=>'Este adjunto está etiquetado como generado por IA, por lo que todos los archivos de abajo deberían llevar la declaración.','This attachment is not labeled as AI-generated. Nothing is written into its files, and no declaration is expected below.'=>'Este adjunto no está etiquetado como generado por IA. No se escribe nada en sus archivos y abajo no se espera ninguna declaración.','no declaration'=>'sin declaración','AI in this text'=>'IA en este texto','Responsible person'=>'Persona responsable','Reviewed by %1$s on %2$s.'=>'Revisado por %1$s el %2$s.','The text or its images changed since; save with the reviewed level again after checking.'=>'El texto o sus imágenes han cambiado desde entonces; tras comprobarlo, guarda de nuevo con el nivel «revisado».','AI levels show a note on the post. The wording, position, excerpt and feed options are in the TransparAI settings.'=>'Los niveles de IA muestran un aviso en la entrada. El texto, la posición y las opciones de extracto y feed están en los ajustes de TransparAI.','AI levels show a note on the post. Wording and placement are set in the TransparAI settings.'=>'Los niveles de IA muestran un aviso en la entrada. El texto y la ubicación se definen en los ajustes de TransparAI.','AI text'=>'Texto IA','changed since review'=>'modificado desde la revisión','All AI levels'=>'Todos los niveles de IA','Any AI involvement'=>'Cualquier participación de IA','Not classified'=>'Sin clasificar','&mdash; No change &mdash;'=>'&mdash; Sin cambios &mdash;','Remove classification'=>'Quitar la clasificación','AI-written text'=>'Texto escrito con IA','Every post carries an AI level (none, AI-assisted, AI-generated, AI-generated and reviewed), set in the editor sidebar, in Quick Edit or in bulk. AI levels show a note on the post; the shortcode [transparai_notice] and the "AI notice" block place it anywhere by hand.'=>'Cada entrada lleva un nivel de IA (ninguno, asistido por IA, generado por IA, generado por IA y revisado), definido en la barra lateral del editor, en la edición rápida o en lote. Los niveles de IA muestran un aviso en la entrada; el shortcode [transparai_notice] y el bloque «Aviso de IA» lo colocan a mano donde quieras.','Note text'=>'Texto del aviso','This text was generated by AI.'=>'Este texto fue generado por IA.','Leave empty for a translated wording per level ("created with the help of AI", "generated by AI", "generated by AI and reviewed by a person").'=>'Déjalo vacío para un texto traducido por nivel («creado con ayuda de IA», «generado por IA», «generado por IA y revisado por una persona»).','Ahead of the content'=>'Antes del contenido','After the content'=>'Después del contenido','Review'=>'Revisión','Name of the person responsible'=>'Nombre de la persona responsable','Default for the "responsible person" of reviewed texts; each post can name someone else. The reviewer, date and a fingerprint of the reviewed text are recorded with the post.'=>'Valor por defecto de la «persona responsable» de los textos revisados; cada entrada puede nombrar a otra. El revisor, la fecha y una huella del texto revisado se guardan con la entrada.','Name the reviewer and the review date in the public note and in the structured data'=>'Nombrar al revisor y la fecha de revisión en el aviso público y en los datos estructurados','New posts'=>'Entradas nuevas','Preselected level for posts created from now on. Existing posts are never reclassified.'=>'Nivel preseleccionado para las entradas creadas a partir de ahora. Las entradas existentes nunca se reclasifican.','Excerpts and feeds'=>'Extractos y feeds','Append the note as plain text to excerpts (archives, teasers, related posts)'=>'Añadir el aviso como texto plano a los extractos (archivos, avances, entradas relacionadas)','Add the note to RSS feed items (content, summary and a machine-readable dc:description element)'=>'Añadir el aviso a los elementos del feed RSS (contenido, resumen y un elemento dc:description legible por máquinas)','This text was generated by AI and reviewed by a person.'=>'Este texto fue generado por IA y revisado por una persona.','No AI used'=>'Sin uso de IA','AI-assisted'=>'Asistido por IA','AI-generated, reviewed by a person'=>'Generado por IA, revisado por una persona','This post has no AI level yet, so the notice stays hidden. Set the level in the document sidebar under TransparAI.'=>'Esta entrada aún no tiene nivel de IA, así que el aviso permanece oculto. Define el nivel en la barra lateral del documento, en TransparAI.','AI notice'=>'Aviso de IA','Style'=>'Estilo','Block (own line)'=>'Bloque (línea propia)','Inline (inside text)'=>'En línea (dentro del texto)','Custom text'=>'Texto personalizado','Leave empty to use the wording from the TransparAI settings.'=>'Déjalo vacío para usar el texto de los ajustes de TransparAI.','block titleAI notice'=>'Aviso de IA','block descriptionPlaces the AI disclosure note of this post where you want it. Renders only when the post has an AI level.'=>'Coloca el aviso de IA de esta entrada donde quieras. Solo se muestra si la entrada tiene un nivel de IA.','block keywordai'=>'ia','block keyworddisclosure'=>'aviso','block keywordtransparency'=>'transparencia','block keywordeu ai act'=>'ai act','camera photo (digitalCapture)'=>'foto de cámara (digitalCapture)','human digital work (digitalCreation)'=>'obra digital humana (digitalCreation)','Not AI:'=>'Sin IA:','This attachment is declared as not AI-made (%s). The declaration is written into files that carry no other digital source type.'=>'Este adjunto está declarado como no creado por IA (%s). La declaración se escribe en los archivos que no llevan otro digital source type.','Declared not AI (camera, human work)'=>'Declarado sin IA (cámara, obra humana)','Declare as camera photo (not AI)'=>'Declarar como foto de cámara (sin IA)','Declare as human work (not AI)'=>'Declarar como obra humana (sin IA)','Remove "not AI" declaration'=>'Quitar la declaración «sin IA»','Not AI'=>'Sin IA','Also show a badge on media declared as camera photo or human work (the structured data carries the declaration either way)'=>'Mostrar también una insignia en los medios declarados como foto de cámara u obra humana (los datos estructurados llevan la declaración de todos modos)','Human made'=>'Hecho por personas','Also write digitalCapture or digitalCreation into media you declared as not AI-made, but never over a declaration another tool or a camera already wrote'=>'Escribir también digitalCapture o digitalCreation en los medios declarados sin IA, pero nunca sobre una declaración que otra herramienta o una cámara ya escribió','short human badge labelHuman'=>'Humano','from %s'=>'antes %s','audit report'=>'informe de auditoría','items'=>'elementos','Document hash'=>'Hash del documento','sha256 over the facts below without timestamps: two reports of an unchanged site carry the same hash.'=>'sha256 de los hechos siguientes sin marcas de tiempo: dos informes de un sitio sin cambios llevan el mismo hash.','Basis'=>'Base','Limitations'=>'Limitaciones','Print or save as PDF'=>'Imprimir o guardar como PDF','Print view'=>'Vista de impresión','The export lists every labeled, declared and pending file with its detection source, confidence, full history and the person behind each change. The print view adds a document hash over the facts, the guidance basis and the stated limitations; the same record is available at /wp-json/transparai/v1/report.'=>'La exportación lista cada archivo etiquetado, declarado o pendiente con su fuente de detección, confianza, historial completo y la persona detrás de cada cambio. La vista de impresión añade un hash del documento sobre los hechos, la base y las limitaciones indicadas; el mismo registro está disponible en /wp-json/transparai/v1/report.']];